const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='little-desk-v1';
let saved;try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch{saved={}}
const state={favorites:[],custom:[],tasks:[],draft:{},alarms:[{id:'a1',title:'1교시 시작',time:'09:00',days:[1,2,3,4,5],enabled:true},{id:'a2',title:'2교시 시작',time:'09:50',days:[1,2,3,4,5],enabled:true},{id:'a3',title:'점심시간',time:'12:10',days:[1,2,3,4,5],enabled:true}],...saved};
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',3000)}
function save(){try{localStorage.setItem(key,JSON.stringify(state));return true}catch{toast('저장 공간을 사용할 수 없습니다. 브라우저 설정을 확인해 주세요.');return false}}
const apps=[{id:'teacher',title:'생존형 교사의 도구함',description:'안내문, 할 일, 모둠 편성까지. 반복 업무를 한 번 덜어내세요.',category:'교사 도구',icon:'✎',color:'',url:'#teacher',tag:'NEW · 새로 만든 앱'},{id:'diary',title:'오늘의 조각',description:'하루의 기분과 작은 이야기를 남기는 나의 개인 일기장. Google 로그인으로 기기 간 기록을 이어가요.',category:'기록',icon:'▤',color:'peach',url:'diary/',tag:'Google 로그인 · 비공개 기록'},{id:'alarm',title:'교실 알람',description:'수업 시작과 쉬는 시간. 시간표에 맞춰 하루의 흐름을 챙겨요.',category:'교사 도구',icon:'◷',color:'blue',url:'#alarm',tag:'기존 교실 알람의 웹 버전'}];
function safeAppUrl(value){try{if(value==='diary/'||['#teacher','#alarm'].includes(value))return value;const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'#home'}catch{return '#home'}}
let category='전체',query='',tool='문장 도우미';
const main=$('#main');
$('#date').textContent=new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'long'}).format(new Date());
function intro(kicker,title,desc,button=''){return `<div class="intro"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${button}</div>`}
function renderCards(){const list=[...apps,...state.custom].filter(a=>(location.hash!=='#favorites'||state.favorites.includes(a.id))&&(category==='전체'||a.category===category)&&`${a.title} ${a.description}`.toLowerCase().includes(query.toLowerCase()));$('#count').textContent=`${list.length}개의 앱`;$('#cards').innerHTML=list.length?list.map(a=>`<article class="card"><div class="card-top"><span class="app-icon ${esc(a.color)}">${esc(a.icon||'↗')}</span><button class="favorite ${state.favorites.includes(a.id)?'on':''}" data-fav="${esc(a.id)}" aria-label="${esc(a.title)} 즐겨찾기" aria-pressed="${state.favorites.includes(a.id)}">${state.favorites.includes(a.id)?'★':'☆'}</button></div><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><div class="badges"><span class="badge">${esc(a.category)}</span><span class="badge">${esc(a.tag||'직접 추가')}</span></div><div class="card-link"><a href="${esc(safeAppUrl(a.url))}" ${safeAppUrl(a.url).startsWith('http')?'target="_blank" rel="noopener noreferrer"':''}>앱 열기 <span aria-hidden="true">↗</span></a>${a.id.startsWith('custom-')?`<button class="remove" data-remove="${esc(a.id)}">삭제</button>`:'<span aria-hidden="true">→</span>'}</div></article>`).join(''):'<div class="empty">아직 앱이 없어요. 필터를 바꾸거나 새 앱을 추가해 보세요.</div>';$('#cards').querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{state.favorites=state.favorites.includes(b.dataset.fav)?state.favorites.filter(x=>x!==b.dataset.fav):[...state.favorites,b.dataset.fav];save();renderCards()});$('#cards').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(!confirm('이 앱의 링크를 서랍에서 삭제할까요?'))return;state.custom=state.custom.filter(a=>a.id!==b.dataset.remove);state.favorites=state.favorites.filter(x=>x!==b.dataset.remove);save();renderCards()})}
function hub(){main.innerHTML=intro('A PLACE FOR YOUR EVERYDAY','나의 작은 앱 서랍','기록하고, 덜 일하고, 나답게 쉬는 도구들을 한곳에.','<button class="primary" id="addApp">＋ 앱 추가</button>')+`<section class="hero"><div><div class="eyebrow">LESS WORK, MORE LIFE</div><h2>열정은 아끼고, 퇴근은 가볍게.</h2><p>생존형 교사를 위한 작은 도구함을 새로 열었어요.</p><a href="#teacher">오늘의 노동 줄이기 <span>↗</span></a></div><div class="desk-art" aria-hidden="true"><div class="notebook"></div><div class="pencil"></div></div></section><div class="section-title"><h2>${location.hash==='#favorites'?'즐겨찾는 앱':'모든 앱'}</h2><span id="count"></span></div><div class="toolbar"><div class="chips">${['전체','교사 도구','기록','생활 도구'].map(c=>`<button class="chip ${category===c?'active':''}" data-cat="${c}">${c}</button>`).join('')}</div><input class="search" id="search" aria-label="앱 검색" placeholder="⌕  어떤 앱을 찾으세요?" value="${esc(query)}"></div><div class="grid" id="cards"></div><div class="notice">⌂ &nbsp; 일기장은 Google 로그인 후 Firebase에 저장됩니다. 기존 PC 일기는 자동으로 업로드되지 않습니다.<br>이 허브의 즐겨찾기·추가 링크·도구 설정은 현재 브라우저에 저장됩니다. 다른 기기와 자동으로 동기화되지 않습니다.</div>`;$('#addApp').onclick=()=>$('#addDialog').showModal();$('#search').oninput=e=>{query=e.target.value;renderCards()};main.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{category=b.dataset.cat;hub()});renderCards()}
$('#closeDialog').onclick=()=>$('#addDialog').close();
$('#addForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);let url;try{url=new URL(f.get('url'));if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw Error()}catch{return toast('http 또는 https 웹 주소를 입력해 주세요.')}state.custom.push({id:'custom-'+crypto.randomUUID(),title:f.get('title').trim(),description:f.get('description').trim(),url:url.href,category:f.get('category'),icon:'↗'});save();$('#addDialog').close();e.target.reset();category='전체';query='';if(['#home','#favorites',''].includes(location.hash))hub();else location.hash='home';toast('서랍에 앱을 추가했어요.')};
function teacher(){main.innerHTML=intro('TEACHER SURVIVAL KIT','열정 없는 생존형 교사의<br>노동을 줄여주는 앱','완벽한 교사보다, 오늘 무사히 퇴근하는 교사. 반복되는 일을 가볍게 해요.')+`<div class="tool-tabs">${['문장 도우미','오늘의 업무','모둠 편성','수업 타이머'].map(t=>`<button data-tool="${t}" class="${t===tool?'active':''}">${t}</button>`).join('')}</div><div id="toolBody"></div><div class="notice">이 도구는 브라우저 안에서 동작합니다. 문장 도우미는 입력한 항목을 정해진 서식에 넣어 초안을 만들며, 전송 전에 내용을 확인해 주세요. 학생 이름이나 연락처 없이도 사용할 수 있습니다.</div>`;main.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;teacher()});({ '문장 도우미':writer,'오늘의 업무':tasks,'모둠 편성':groups,'수업 타이머':timerView}[tool])()}
const field=(name,label,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" maxlength="300"></label>`;
function writer(){const d=state.draft;$('#toolBody').innerHTML=`<div class="workspace"><form class="panel" id="writer"><h2>핵심만 적어 주세요</h2><label>문서 종류<select name="kind">${['학부모 안내','준비물 안내','제출 독촉','회의 안내'].map(x=>`<option ${d.kind===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('topic','무슨 내용인가요?',d.topic||'')}${field('when','일시 / 마감',d.when||'')}${field('item','준비물 / 제출 항목',d.item||'')}${field('place','장소 / 제출 방법',d.place||'')}<label>덧붙일 내용<textarea name="extra" maxlength="1500">${esc(d.extra||'')}</textarea></label><button class="primary" type="submit">안내문 초안 만들기 →</button><p class="muted">입력한 항목만 조합하는 서식 도구입니다.</p></form><section class="panel"><div class="section-title"><h2>바로 쓰는 초안</h2><span>직접 수정 가능</span></div><label class="tiny" for="result">완성 문장</label><textarea id="result" class="output" placeholder="왼쪽에서 내용을 입력해 주세요.">${esc(d.result||'')}</textarea><div class="actions"><button id="copy">문장 복사</button><button id="download">TXT 저장</button></div></section></div>`;$('#writer').onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));if(!x.topic.trim())return toast('안내할 내용을 적어 주세요.');const lines=[`[${x.topic.trim()} 안내]`,'',x.kind==='회의 안내'?'안녕하세요. 다음과 같이 회의를 안내드립니다.':'안녕하세요. 학부모님께 안내드립니다.','',x.kind==='제출 독촉'?`${x.topic.trim()} 제출 여부를 확인하시고, 아직 제출하지 않으셨다면 아래 내용을 확인하여 제출해 주시기 바랍니다.`:`${x.topic.trim()}에 관해 아래와 같이 안내드립니다.`,'',x.when&&`• ${x.kind==='제출 독촉'?'제출 마감':'일시 / 마감'}: ${x.when.trim()}`,x.item&&`• ${x.kind==='준비물 안내'?'준비물':'준비 / 제출 항목'}: ${x.item.trim()}`,x.place&&`• 장소 / 방법: ${x.place.trim()}`,x.extra&&`\n${x.extra.trim()}`,'','확인해 주셔서 감사합니다.'];x.result=lines.filter(s=>s!==false&&s!==undefined).join('\n').replace(/\n{3,}/g,'\n\n');state.draft=x;save();$('#result').value=x.result;toast('초안을 만들었어요. 필요한 부분을 수정해 주세요.')};$('#result').oninput=e=>{state.draft.result=e.target.value;save()};$('#copy').onclick=()=>copy($('#result').value);$('#download').onclick=()=>download('안내문.txt',$('#result').value,'text/plain;charset=utf-8')}
async function copy(s){if(!s.trim())return toast('먼저 내용을 만들어 주세요.');try{await navigator.clipboard.writeText(s);toast('복사했어요.')}catch{toast('복사를 사용할 수 없습니다. 문장을 선택해 직접 복사해 주세요.')}}
function download(name,text,type){if(!text.trim())return toast('저장할 내용이 없어요.');const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function tasks(){const done=state.tasks.filter(x=>x.done).length;$('#toolBody').innerHTML=`<div class="panel"><div class="section-title"><h2>오늘은 여기까지만</h2><span>${done} / ${state.tasks.length} 완료</span></div><form id="taskForm" class="row"><input id="taskInput" aria-label="추가할 업무" placeholder="가장 먼저 끝낼 일 하나" maxlength="150" required><button class="primary">＋ 추가</button></form><div id="taskList">${state.tasks.map(t=>`<div class="task ${t.done?'done':''}"><input type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''} aria-label="${esc(t.text)} 완료"><span>${esc(t.text)}</span><button data-delete="${esc(t.id)}" aria-label="업무 삭제">×</button></div>`).join('')||'<p class="empty">아직 등록한 업무가 없어요. 꼭 해야 할 일부터 적어 보세요.</p>'}</div><div class="actions"><button id="clearDone">완료한 업무 정리</button><button id="taskExport">목록 TXT 저장</button></div><p class="muted">목록은 브라우저를 닫아도 유지됩니다. 직접 지울 때까지 남아 있어요.</p></div>`;$('#taskForm').onsubmit=e=>{e.preventDefault();const text=$('#taskInput').value.trim();if(!text)return;state.tasks.push({id:crypto.randomUUID(),text,done:false});save();tasks();$('#taskInput').focus()};main.querySelectorAll('[data-task]').forEach(el=>el.onchange=()=>{state.tasks.find(t=>t.id===el.dataset.task).done=el.checked;save();tasks()});main.querySelectorAll('[data-delete]').forEach(el=>el.onclick=()=>{state.tasks=state.tasks.filter(t=>t.id!==el.dataset.delete);save();tasks()});$('#clearDone').onclick=()=>{state.tasks=state.tasks.filter(t=>!t.done);save();tasks()};$('#taskExport').onclick=()=>download('업무목록.txt',state.tasks.map(t=>`${t.done?'[완료]':'[ ]'} ${t.text}`).join('\n'),'text/plain;charset=utf-8')}
function groups(){ $('#toolBody').innerHTML=`<div class="workspace"><form class="panel" id="groupForm"><h2>이름 없이 모둠 나누기</h2><div class="row"><label>전체 학생 수<input id="students" type="number" min="2" max="100" value="24" required></label><label>모둠 수<input id="groupCount" type="number" min="2" max="30" value="6" required></label></div><label>제외할 번호 (선택)<input id="exclude" placeholder="예: 3, 12, 19"></label><p class="muted">1번부터 번호로 무작위 배정합니다.<br>모둠별 인원 차이는 최대 1명입니다.</p><button class="primary">모둠 편성하기</button></form><div class="panel"><h2>편성 결과</h2><div id="groupResult" class="muted">번호만으로 간단하게, 개인정보 없이.</div><div class="actions"><button id="groupCopy">결과 복사</button></div></div></div>`;let output='';$('#groupForm').onsubmit=e=>{e.preventDefault();const n=Number($('#students').value),g=Number($('#groupCount').value),raw=$('#exclude').value.trim();const tokens=raw?raw.split(/[,\s]+/).filter(Boolean):[];if(tokens.some(t=>!/^\d+$/.test(t)||+t<1||+t>n))return toast('제외 번호는 전체 학생 수 안의 정수로 입력해 주세요.');const excluded=new Set(tokens.map(Number));const nums=Array.from({length:n},(_,i)=>i+1).filter(x=>!excluded.has(x));if(g>nums.length)return toast('모둠 수가 참여 학생 수보다 많아요.');for(let i=nums.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[nums[i],nums[j]]=[nums[j],nums[i]]}const result=Array.from({length:g},()=>[]);nums.forEach((x,i)=>result[i%g].push(x));output=result.map((a,i)=>`${i+1}모둠: ${a.join(', ')}번`).join('\n');$('#groupResult').innerHTML=result.map((a,i)=>`<div class="group"><strong>${i+1}모둠</strong><br>${a.map(x=>x+'번').join(' · ')}</div>`).join('')};$('#groupCopy').onclick=()=>copy(output)}
let timer={seconds:300,end:0,running:false};
function remaining(){return timer.running?Math.max(0,Math.ceil((timer.end-Date.now())/1000)):timer.seconds}
function timeText(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function timerView(){$('#toolBody').innerHTML=`<div class="panel"><h2>설명은 짧게, 시간은 눈에 띄게</h2><div class="chips">${[1,3,5,10,20,40].map(n=>`<button data-min="${n}">${n}분</button>`).join('')}</div><div class="timer" id="timerClock" role="timer">${timeText(remaining())}</div><form id="timerForm" class="row"><label>직접 설정 (분)<input type="number" id="minutes" min="1" max="180" value="5" required></label><button>시간 설정</button></form><div class="actions"><button class="primary" id="timerStart">시작</button><button id="timerPause">일시정지</button><button id="timerReset">초기화</button><button id="focusView">크게 보기</button></div><p class="muted">페이지를 열어 두면 종료 시 소리가 울립니다. 새로고침하면 타이머가 초기화됩니다.</p></div>`;const set=n=>{timer={seconds:n*60,end:0,running:false};$('#timerClock').textContent=timeText(timer.seconds)};main.querySelectorAll('[data-min]').forEach(b=>b.onclick=()=>set(+b.dataset.min));$('#timerForm').onsubmit=e=>{e.preventDefault();set(+$('#minutes').value)};$('#timerStart').onclick=()=>{audioReady();if(!timer.running&&timer.seconds>0){timer.end=Date.now()+timer.seconds*1000;timer.running=true}};$('#timerPause').onclick=()=>{timer.seconds=remaining();timer.running=false};$('#timerReset').onclick=()=>set(5);$('#focusView').onclick=()=>{document.body.classList.toggle('wide');$('#focusView').textContent=document.body.classList.contains('wide')?'기본 보기':'크게 보기'}}
let audio;function audioReady(){try{audio ||= new(window.AudioContext||window.webkitAudioContext)();audio.resume()}catch{}}
function beep(){if(!audio)return;try{for(let i=0;i<3;i++){const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=660;g.gain.value=.12;const t=audio.currentTime+i*.4;o.start(t);g.gain.exponentialRampToValueAtTime(.001,t+.3);o.stop(t+.3)}}catch{}}
let alarmsActive=false,previousTick=Date.now();
function alarm(){main.innerHTML=intro('CLASSROOM RHYTHM','교실의 하루를, 제시간에.','기존 교실 알람을 바탕으로 만든 가벼운 웹 버전. 기본 시간표를 내 수업에 맞게 바꾸세요.')+`<div class="workspace"><section class="panel"><div class="eyebrow">LOCAL TIME</div><div class="clock" id="clock"></div><div id="alarmSignal">${alarmsActive?'알람이 켜져 있어요.':'알람 시작을 누르면 소리를 사용할 수 있어요.'}</div><button class="primary" id="enableAlarm">${alarmsActive?'알람 일시정지':'알람 시작'}</button><p class="muted">웹 버전은 이 페이지가 열려 있어야 작동합니다. 절전·백그라운드 제한 시 알림이 지연될 수 있습니다. Google Sheets 연동은 기존 Windows 앱에서 사용해 주세요.</p></section><section class="panel"><h2>나의 시간표</h2><div id="alarmList">${state.alarms.map(a=>`<div class="alarm-line"><input type="checkbox" data-toggle="${a.id}" ${a.enabled?'checked':''} aria-label="${esc(a.title)} 사용"><strong>${esc(a.title)}<br><span class="muted">${a.days.map(x=>'일월화수목금토'[x]).join(' · ')}</span></strong><input type="time" data-time="${a.id}" value="${a.time}" aria-label="${esc(a.title)} 시각"><button class="icon-btn" data-delete-alarm="${a.id}" aria-label="알람 삭제">×</button></div>`).join('')||'<p class="muted">등록한 알람이 없어요.</p>'}</div><form id="alarmForm"><div class="row"><label>알람 이름<input name="title" maxlength="80" required placeholder="예: 3교시 시작"></label><label>시각<input type="time" name="time" required value="10:40"></label></div><label>반복 요일<select name="days"><option value="1,2,3,4,5">월~금</option><option value="0,1,2,3,4,5,6">매일</option>${[1,2,3,4,5,6,0].map(d=>`<option value="${d}">${'일월화수목금토'[d]}요일</option>`).join('')}</select></label><button>＋ 알람 추가</button></form></section></div>`;$('#enableAlarm').onclick=()=>{audioReady();alarmsActive=!alarmsActive;previousTick=Date.now();if(alarmsActive)beep();alarm()};main.querySelectorAll('[data-toggle]').forEach(b=>b.onchange=()=>{state.alarms.find(x=>x.id===b.dataset.toggle).enabled=b.checked;save()});main.querySelectorAll('[data-time]').forEach(b=>b.onchange=()=>{if(!b.value){alarm();return}state.alarms.find(x=>x.id===b.dataset.time).time=b.value;save()});main.querySelectorAll('[data-delete-alarm]').forEach(b=>b.onclick=()=>{state.alarms=state.alarms.filter(x=>x.id!==b.dataset.deleteAlarm);save();alarm()});$('#alarmForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.get('title').trim())return;state.alarms.push({id:crypto.randomUUID(),title:f.get('title').trim(),time:f.get('time'),days:f.get('days').split(',').map(Number),enabled:true});state.alarms.sort((a,b)=>a.time.localeCompare(b.time));save();alarm()}}
setInterval(()=>{const now=new Date();if($('#clock'))$('#clock').textContent=now.toLocaleTimeString('ko-KR',{hour12:false});if(timer.running){const r=remaining();if($('#timerClock'))$('#timerClock').textContent=timeText(r);if(r===0){timer.running=false;timer.seconds=0;beep();toast('설정한 시간이 끝났어요.')}}if(alarmsActive){for(const a of state.alarms){const at=new Date(now);const [h,m]=a.time.split(':').map(Number);at.setHours(h,m,0,0);if(a.enabled&&a.days.includes(now.getDay())&&at.getTime()>previousTick&&at<=now&&now-previousTick<90000){beep();toast(a.title+' 시간이에요.');if($('#alarmSignal'))$('#alarmSignal').textContent=a.title+' · '+a.time}}}previousTick=now.getTime()},250);
function route(){document.body.classList.remove('wide');const r=location.hash.slice(1)||'home';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===r);if(a.dataset.nav===r)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#crumb').textContent=({home:'나의 앱 서랍',favorites:'즐겨찾기',teacher:'생존형 교사 도구',alarm:'교실 알람'})[r]||'나의 앱 서랍';if(r==='teacher')teacher();else if(r==='alarm')alarm();else hub();window.scrollTo(0,0)}
addEventListener('hashchange',route);route();
